param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'numberformatinfo-provider-selection-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Decode($Spec,$Encoded){if([object]::ReferenceEquals($Encoded,$null)){$v=$null}elseif($Spec.kind -eq 'int'){$v=[int]$Encoded}elseif($Spec.kind -eq 'array'){$v=[int[]]$Encoded}else{$v=-join [char[]][int[]]$Encoded};return ,$v}
function New-Seed{$n=[Globalization.NumberFormatInfo]::new();foreach($spec in $plan.properties){[Globalization.NumberFormatInfo].GetProperty($spec.name).SetValue($n,(Decode $spec $spec.seed))};return $n}
function Snapshot($N){$values=[ordered]@{};foreach($spec in $plan.properties){$v=[Globalization.NumberFormatInfo].GetProperty($spec.name).GetValue($N);if($spec.kind -eq 'string'){$values[$spec.name]=[int[]][char[]]$v}elseif($spec.kind -eq 'array'){$values[$spec.name]=[int[]]$v}else{$values[$spec.name]=[int]$v}};return [ordered]@{readOnly=$N.IsReadOnly;values=$values}}
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null});actualValue=$(if($e -is [ArgumentOutOfRangeException]){$e.ActualValue}else{$null})}}

$assembly=[Reflection.Emit.AssemblyBuilder]::DefineDynamicAssembly([Reflection.AssemblyName]::new('NfiProviderOracle'),[Reflection.Emit.AssemblyBuilderAccess]::Run);$module=$assembly.DefineDynamicModule('NfiProviderOracle');$builder=$module.DefineType('OracleFormatProvider',[Reflection.TypeAttributes]::Public,[object],[type[]]@([IFormatProvider]));[void]$builder.DefineDefaultConstructor([Reflection.MethodAttributes]::Public);$calls=$builder.DefineField('Calls',[int],[Reflection.FieldAttributes]::Public);$lastType=$builder.DefineField('LastType',[type],[Reflection.FieldAttributes]::Public);$returnValue=$builder.DefineField('ReturnValue',[object],[Reflection.FieldAttributes]::Public);$throws=$builder.DefineField('Throws',[bool],[Reflection.FieldAttributes]::Public);$m=$builder.DefineMethod('GetFormat',[Reflection.MethodAttributes]'Public,Virtual,Final,NewSlot,HideBySig',[object],[type[]]@([type]));$il=$m.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Dup);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$calls);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Add);$il.Emit([Reflection.Emit.OpCodes]::Stfld,$calls);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Stfld,$lastType);$normal=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$throws);$il.Emit([Reflection.Emit.OpCodes]::Brfalse,$normal);$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'provider failure');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$il.MarkLabel($normal);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$returnValue);$il.Emit([Reflection.Emit.OpCodes]::Ret);$builder.DefineMethodOverride($m,[IFormatProvider].GetMethod('GetFormat'));$providerType=$builder.CreateType()
$current=[Globalization.NumberFormatInfo]::CurrentInfo;if(-not [object]::ReferenceEquals($current,[Globalization.NumberFormatInfo]::InvariantInfo)){throw 'Invariant current provider precondition required'};$currentSnapshot=Snapshot $current;$rows=[Collections.Generic.List[object]]::new()
foreach($profile in $plan.providerProfiles){$mutable=New-Seed;$readOnly=[Globalization.NumberFormatInfo]::ReadOnly($mutable);$clone=[Globalization.NumberFormatInfo]$readOnly.Clone();$callback=$null
 switch($profile){'null'{$provider=$null};'directMutable'{$provider=$mutable};'directReadonly'{$provider=$readOnly};default{$callback=[Activator]::CreateInstance($providerType);$provider=$callback}}
 for($round=0;$round -lt 4;$round++){
  if(-not [object]::ReferenceEquals($callback,$null)){switch($profile){'callbackNull'{$callback.ReturnValue=$null};'callbackString'{$callback.ReturnValue='wrong'};'callbackInt'{$callback.ReturnValue=7};'callbackMutable'{$callback.ReturnValue=$mutable};'callbackReadonly'{$callback.ReturnValue=$readOnly};'callbackClone'{$callback.ReturnValue=$clone};'callbackThrow'{$callback.ReturnValue=$mutable;$callback.Throws=$true};'callbackSequence'{switch($round){0{$callback.ReturnValue=$null};1{$callback.ReturnValue=$mutable};2{$callback.ReturnValue=$readOnly};3{$callback.ReturnValue=$null}}}}}
  try{$value=[Globalization.NumberFormatInfo]::GetInstance($provider);$identity=if([object]::ReferenceEquals($value,$current)){'current'}elseif([object]::ReferenceEquals($value,$mutable)){'mutable'}elseif([object]::ReferenceEquals($value,$readOnly)){'readonly'}elseif([object]::ReferenceEquals($value,$clone)){'clone'}else{throw 'Unexpected provider identity'};$result=[ordered]@{ok=$true;identity=$identity;snapshot=(Snapshot $value)}}catch{$result=Failure $_}
  $rows.Add([ordered]@{profile=$profile;round=$round;result=$result;calls=$(if([object]::ReferenceEquals($callback,$null)){0}else{$callback.Calls});lastType=$(if([object]::ReferenceEquals($callback,$null) -or [object]::ReferenceEquals($callback.LastType,$null)){$null}else{$callback.LastType.FullName})})
 }
}
if($rows.Count -ne 44){throw 'Wrong provider selection matrix'}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';currentSnapshot=$currentSnapshot;rows=$rows.ToArray();qualification='SELECTED_INVARIANT_GETINSTANCE_PROVIDER_IDENTITY_CALLBACK_AND_FALLBACK_ONLY; CURRENT_CULTURE_CULTUREINFO_FASTPATH_OTHER_FIELDS_FULL_METADATA_AND_TASK_ACCEPTANCE_OPEN'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 24 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS GetInstance reference: 11 providers, 44 calls'
